/**
 * @vitest-environment jsdom
 *
 * Two real, compounding bugs, found during Section 2.5 investigation of what had been
 * misdiagnosed twice earlier this session as "esbuild-service flakiness" in
 * bindingParitySnapshot.test.ts's GridDetail fixture (same fixed byte offset, different
 * garbled character each failure — looked exactly like IPC corruption under parallel load).
 *
 * Bug 1 — hyphenated node id breaks dot notation: every node id in this codebase is
 * generated by `createNodeId` in state.ts as `<itemId>-<Date.now()>-<random>` — always
 * hyphenated. `heroui.modal`'s (and `heroui.drawer`'s) exported `isOpen` attribute, when
 * driven by a showHide Dynamic Action or a GridDetail flow, was built via raw dot-notation
 * string interpolation: `` `isOpen={store.${visibilityPath} === true}` ``. For a node id
 * like "heroui-modal-1784195632573-7w6vn", that produces
 * `store.ui.visibility.heroui-modal-...`, which is NOT a property-access chain — `-` is the
 * subtraction operator, so this parses as a subtraction chain, syntactically invalid
 * wherever the trailing random-suffix token didn't happen to parse as a continuation. That's
 * why it only intermittently produced a *syntax* error rather than always failing outright.
 *
 * Bug 2 — wrong root identifier: the generated component's preamble destructures
 * `const { store: designerStore, patch: patchDesignerStore } = useDesignerStore(...)` — a
 * bare `store` identifier is never actually declared in scope. Fixing only Bug 1 (bracket
 * notation) would still leave `store.ui.visibility[...]` referencing an undeclared variable,
 * throwing `ReferenceError: store is not defined` at runtime — a bug that ts.transpileModule
 * / esbuild's syntax-only checks can never catch, since it's a scope/semantic issue, not a
 * parse error. Confirmed by inspecting the actual generated preamble text.
 *
 * Combined: any published app with a Modal or Drawer whose visibility is controlled by a
 * Dynamic Action or a GridDetail row-action flow could ship with code that either failed to
 * compile at all, or compiled but crashed at runtime the moment the modal/drawer was opened.
 *
 * Fixed via `buildStorePathAccessExpression('designerStore', path)` (visibilityConditionEngine.ts),
 * which both roots the expression at the actually-declared identifier and uses bracket
 * notation for any path segment that isn't a valid JS identifier.
 */
import { describe, expect, it } from 'vitest';
import { createInitialDesignerState, designerReducer } from '../state';
import { generateDesignerTsx } from '../codegen';
import { createDynamicActionsEventBindingDefinition, eventBindingKeyForEvent } from '../bindingEngine';
import { createDynamicAction } from '../bindingDynamicActionsEngine';
import { assertValidTsxSyntax } from './tsxSyntaxCheck';

describe('Modal/Drawer visibility store path — hyphenated node id + wrong root identifier (real bugs, not infra flake)', () => {
  it('generates syntactically valid, correctly-rooted, bracket-notation isOpen for heroui.modal driven by a showHide action', () => {
    let state = createInitialDesignerState();
    state = designerReducer(state, { type: 'insert-palette-item', itemId: 'heroui.button-solid', parentId: state.document.rootNodeId });
    const buttonId = state.document.nodes[state.document.rootNodeId].children.at(-1)!;

    state = designerReducer(state, { type: 'insert-palette-item', itemId: 'heroui.modal', parentId: state.document.rootNodeId });
    const modalId = state.document.nodes[state.document.rootNodeId].children.at(-1)!;
    // Node ids are always hyphenated (state.ts's createNodeId) — assert that premise holds,
    // so this test can never silently stop exercising the bug if id generation ever changes.
    expect(modalId).toMatch(/heroui-modal-\d+-\w+/);

    const showAction = createDynamicAction('showHide');
    showAction.targetNodeId = modalId;
    showAction.showHideEffect = 'show';
    state = designerReducer(state, {
      type: 'set-node-binding',
      nodeId: buttonId,
      bindingKey: eventBindingKeyForEvent('onClick'),
      definition: createDynamicActionsEventBindingDefinition('onClick', [showAction]),
    });

    const tsx = generateDesignerTsx(state.document, state.bindingDefinitions);

    expect(() => assertValidTsxSyntax('heroui.modal showHide', tsx)).not.toThrow();
    // Confirms the actually-declared preamble identifier this must be rooted at.
    expect(tsx).toContain('store: designerStore');
    // The isOpen attribute specifically must be rooted at designerStore and use bracket
    // notation — this is the one place the hyphenated id was interpolated as raw code.
    // Elsewhere in the file the same path legitimately appears as a JSON-stringified
    // *string literal* (the evaluateDesignerCondition condition argument, itself resolved
    // against designerStore internally), which is always safe and not what this test covers.
    expect(tsx).toContain(`isOpen={designerStore.ui.visibility["${modalId}"] === true}`);
    expect(tsx).not.toContain(`isOpen={store.`);
    expect(tsx).not.toContain(`isOpen={designerStore.ui.visibility.${modalId}`);
  });

  it('generates syntactically valid, correctly-rooted, bracket-notation isOpen for heroui.drawer driven by a showHide action', () => {
    let state = createInitialDesignerState();
    state = designerReducer(state, { type: 'insert-palette-item', itemId: 'heroui.button-solid', parentId: state.document.rootNodeId });
    const buttonId = state.document.nodes[state.document.rootNodeId].children.at(-1)!;

    state = designerReducer(state, { type: 'insert-palette-item', itemId: 'heroui.drawer', parentId: state.document.rootNodeId });
    const drawerId = state.document.nodes[state.document.rootNodeId].children.at(-1)!;
    expect(drawerId).toMatch(/heroui-drawer-\d+-\w+/);

    const showAction = createDynamicAction('showHide');
    showAction.targetNodeId = drawerId;
    showAction.showHideEffect = 'show';
    state = designerReducer(state, {
      type: 'set-node-binding',
      nodeId: buttonId,
      bindingKey: eventBindingKeyForEvent('onClick'),
      definition: createDynamicActionsEventBindingDefinition('onClick', [showAction]),
    });

    const tsx = generateDesignerTsx(state.document, state.bindingDefinitions);

    expect(() => assertValidTsxSyntax('heroui.drawer showHide', tsx)).not.toThrow();
    expect(tsx).toContain('store: designerStore');
    expect(tsx).toContain(`isOpen={designerStore.ui.visibility["${drawerId}"] === true}`);
    expect(tsx).not.toContain(`isOpen={store.`);
    expect(tsx).not.toContain(`isOpen={designerStore.ui.visibility.${drawerId}`);
  });
});
